/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; children: ReactNode; onInspect: () => void;
